data.mutation:
mutation ($create: [InventoryCreatePayloadInput!]!, $update : [InventoryUpdatePayloadInput!]! ) {
   createInventory(payload: $create) {
    id
    number
    productStrategyProcessId
    locationId
    grossWeight 
    tareWeight 
    netWeight 
    quantity {
      value
      unitId
    }
},
   updateInventory(payload : $update){
   id
    number
    productStrategyProcessId
    locationId

    grossWeight 
    tareWeight 
    netWeight 
    quantity {
      value
      unitId
    }
}
}

data.variablesTransform:
(
  $CONSTANTS := $state.context.CONSTANTS;
  $SETUP := $CONSTANTS.PRODUCTION_SETUP;
  $DEFAULTS := $CONSTANTS.DEFAULTS.PRODUCTION;
  $PRODUCTION_INPUT :=  $CONSTANTS.PRODUCTION_INPUT;
  $productionQuantity :=  $coalesce([$state.context.productionQuantity.quantity,0]);
  $shift := $executeTransform('getShift',
  {
    "date": $moment()
  });

  $operatingTime := $SETUP.productionSetup.mode.operatingTime;
  $includeProduction := $SETUP.productionSetup.mode.includeProductionCounts;
  $standardRate := $coalesce([$SETUP.workOrderDistribution.standardRate, $SETUP.productStrategyProcess.standardRate,0]);
  $productionOperators :=  $coalesce([$SETUP.workOrderDistribution.productionOperators,0]);
  $earnedLaborHours :=  ($productionOperators * $productionQuantity)/$standardRate;
  $earnedMachineHours :=  $productionQuantity/$standardRate;
  {
    "payload": [
      $state.context.CONSTANTS.toInventory.{
        "create": {
          "quantity": $productionQuantity,
          "occurAt": $moment(),
          "productionHistoryStatusId": $DEFAULTS.productionHistoryStatusId,
          "workcenterId": $SETUP.workcenterId,
          "productStrategyProcessId": $SETUP.productStrategyProcessId,
          "transactionTypeId": $DEFAULTS.transactionTypeId,
          "shiftId": $shift[0].id,
          "inventoryId": $.id,
          "workOrderId":$SETUP.workOrderId,
          "workOrderProcessId":$SETUP.workOrderProcessId,
          "earnedMachineHours": $earnedMachineHours,
          "earnedLaborHours": $earnedLaborHours,
          /*IMPORTANT: Calculate actual hours based on previous prod history and operator statuses. For now use earned as placeholder */
           "actualMachineHours":  $moment().diff($SETUP.updatedAt, 'hours',true),
          "actualLaborHours": $moment().diff($SETUP.updatedAt, 'hours', true) * $coalesce([$SETUP.productionSetup.operators.total,0]),
          "workOrderProcessDistributionId": $SETUP.workOrderDistributionId

        }
      }
    ]
  }
)

