data.query:
query Query($where: ProductionSetupOutputWhereInput!, $orderBy: [ProductionSetupOutputOrderByInput!], $first: Int, $after: String) {
  productionSetupOutput(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        updatedAt
        counterInput
        producedQuantity
        scrappedQuantity
        unitPerCycle
        workcenterId
        workOrderId
        workOrderProcessId
        workOrderDistributionId
        productId
        productStrategyProcessId
        productStrategyProcess {
          unitWeight
          productStrategyId
          productionOperators
          standardRate
          productStrategy {
            id
            inventoryUnitId
          }
        }
        productionSetup {
          id
          operators {
            total
          }
          modeId
          mode {
            id
            operatingTime

          }
          eventId
        }
        workcenter {
          code
          id
          name
          shiftGroupId
          globalStandardRate
          productionOperators
          locationId

        }
        workOrderDistribution {
          coDistributions {
            edges {node {id}}
          }
          id
          setupOperators
          productionOperators
          standardRate
          distributionGroup {
            id distributions {
              edges {node{id leadingDistributionId}}
          }
          }
        }

        setupBoms {
          edges {
            node {
              standardUsage
              componentProductStrategyProcessId
            }
          }
        }
      }
    }
  }
}

