data.transform:
const productionSetupMaterial = $.productionSetupMaterial
const productionSetupBOM = $.productionSetupBOM

if (!productionSetupMaterial.edges || !productionSetupMaterial.edges.length || !productionSetupBOM.edges || !productionSetupBOM.edges.length) return false
const q = $state.context.CONSTANTS.REQUEST.productionInput  ? $state.context.CONSTANTS.REQUEST.productionInput.productionQuantity : $state.context.CONSTANTS.REQUEST.scrapInput.scrapQuantity
const m = productionSetupMaterial.edges.reduce((a,c)=> {
  const pid = c.node.inventory.productStrategyProcessId
  a[pid] ? a[pid] = a[pid] + c.node.inventory.quantity.value :  a[pid] = c.node.inventory.quantity.value

  return a
},{})

let result = true;
productionSetupBOM.edges.every(i=>{
  if(!m[i.node.componentProductStrategyProcessId] || m[i.node.componentProductStrategyProcessId] < i.node.standardUsage * q){ 
    result = false
    return false
  } return true
})

return result

